examples.template:
MonarchDeviceList(
    devices = devices,
    title = {{title}},
    description = {{description}},
    now = {{now|millis}},
    onRemove = { id ->
        // The app signs the device out on its server here.
        devices = devices.filterNot { it.id == id }
    },
)

